@pytest.mark.parametrize(
    "line,expected",
    [
        ("Dispersion correction           -0.156179391", -0.156179391),
        ("Dispersion correction            -0.0075031870", -0.0075031870),
        ("Dispersion correction :         -0.020000000 Eh", -0.02),
        ("Dispersion correction   -8.4406062502E-03 Eh", -8.4406062502e-3),
        ("Dispersion correction            0.001000000", 0.001),
    ],
)
def test_summary_line_layouts_are_tolerated(line, expected):
    match = ORCA.re_dispersion_energy.match(line.strip())
    assert match is not None
    assert abs(float(match.group("energy")) - expected) < 1.0e-12


